function r(e){return{costs:e.parcels.filter(n=>n.nature==="cost"),taxes:e.parcels.filter(n=>n.nature==="tax")}}function u(e){return e.parcels.filter(n=>n.source==="missing").length}function c(e){return e.trim().startsWith("-")}function i(e){if(e===null)return null;const[n="0",t=""]=e.split(".");return`${n},${`${t}00`.slice(0,2)}%`}function s(e){return e.revenueDocumentCount===e.revenueExpectedCount?null:{expected:e.revenueExpectedCount,measured:e.revenueDocumentCount}}export{u as c,s as d,i as f,c as i,r as s};
